class Window_EquipStackPicker extends Window_Selectable {
  initialize() {
    this._items = [];
    super.initialize(new Rectangle(0, 0, 534, 384));
    this.hide();
    this.deactivate();
  }
  maxItems() { return this._items.length; }
  itemHeight() { return 88; }
  item() { return this._items[this.index()] || null; }
  drawItem(index) {
    const item = this._items[index];
    if (!item) return;
    const rect = this.itemRect(index);
    const x = rect.x + 86;
    const width = rect.width - 96;
    drawEquipIcon(this.contents, item, rect.x + 6, rect.y + 6, 72);
    this.resetFontSettings();
    const weapon = DataManager.isWeapon(item);
    this.contents.fontSize = 23;
    this.drawText(item.name, x, rect.y + (weapon ? 5 : 23), width);
    if (weapon) {
      this.contents.fontSize = 18;
      const durability = item.durability ?? 0;
      const label = item.durMax > 0
        ? '耐久 ' + durability + '/' + item.durMax + '（' + Math.floor(durability / item.durMax * 100) + '%）'
        : '耐久 —';
      this.drawText(label, x, rect.y + 42, width);
    }
    this.resetFontSettings();
  }
  updateHelp() { this._helpWindow?.setText(description(this.item())); }
  onTouchOk() {
    const index = this.hitIndex();
    if (index < 0) return;
    this.select(index);
    super.onTouchOk();
  }
  showItems(items, grid) {
    this._items = items;
    const height = Math.min(4, items.length) * this.itemHeight() + this.padding * 2 + 8;
    this.move(grid.x + Math.floor((grid.width - this.width) / 2), grid.y + Math.floor((grid.height - height) / 2),
      this.width, height);
    this.createContents();
    this.scrollTo(0, 0);
    this.refresh();
    this.show();
    this.activate();
    this.select(0);
  }
}

